"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[492],{3036:n=>{n.exports=JSON.parse('{"functions":[{"name":"new","desc":"Creates a new Signal object\\n\\n```lua\\nlocal Signal = NewSignal.new()\\n```","params":[],"returns":[{"desc":"","lua_type":"Signal"}],"function_type":"static","source":{"line":443,"path":"src/NewSignal.luau"}},{"name":"Connect","desc":"Connects a function to the signal, which will be called everytime the signal is fired.\\n\\n```lua\\nSignal:Connect(function(Message, Number)\\n\\tprint(Message, Number)\\nend)\\n\\nSignal:Fire(\\"Hello\\", 25)\\n```","params":[{"name":"Callback","desc":"","lua_type":"(...) -> ()"}],"returns":[{"desc":"","lua_type":"Connection"}],"function_type":"method","source":{"line":460,"path":"src/NewSignal.luau"}},{"name":"Once","desc":"Connects a function to the signal, which will be called once and disconnected immediatly.\\n\\n```lua\\nSignal:Once(function(Message, Number)\\n\\tprint(Message, Number)\\nend)\\n\\nSignal:Fire(\\"Hello\\", 25)\\nSignal:Fire(\\"This message will not get printed\\", 10)\\n```","params":[{"name":"Callback","desc":"","lua_type":"(...) -> ()"}],"returns":[{"desc":"","lua_type":"Connection"}],"function_type":"method","source":{"line":478,"path":"src/NewSignal.luau"}},{"name":"Wait","desc":"Yields the current thread until `:Fire` occurs, and returns the arguments fired from the signal.\\n\\n```lua\\ntask.spawn(function()\\n\\tprint(Signal:Wait()) --\x3e \\"Test\\", 89, nil, false\\nend)\\nSignal:Fire(\\"Test\\", 89, nil, false)\\n```","params":[],"returns":[{"desc":"","lua_type":"... any"}],"function_type":"method","yields":true,"source":{"line":500,"path":"src/NewSignal.luau"}},{"name":"FireSync","desc":"Fires a Signal object with the arguments passed.\\n\\n```lua\\nSignal:Connect(function(Text)\\n\\tprint(Text) --\x3e \\"Something...\\"\\nend)\\n\\nSignal:FireSync(\\"Something...\\")\\n```","params":[{"name":"...","desc":"","lua_type":"any"}],"returns":[],"function_type":"method","source":{"line":546,"path":"src/NewSignal.luau"}},{"name":"FireAsync","desc":"Fires a Signal object Asynchronously with the arguments passed.\\n\\n```lua\\nSignal:Connect(function(Text)\\n\\tprint(Text) --\x3e \\"Something...\\"\\nend)\\n\\nSignal:FireAsync(\\"Something...\\")\\n```","params":[{"name":"...","desc":"","lua_type":"any"}],"returns":[],"function_type":"method","source":{"line":574,"path":"src/NewSignal.luau"}},{"name":"FireDeferred","desc":"Fires a Signal object with the arguments passed with a `task.defer`.\\nDoesn\'t take use of the thread recicling protocol.\\n\\n```lua\\nSignal:Connect(function(Text)\\n\\tprint(Text) --\x3e \\"Something...\\"\\nend)\\n\\nSignal:FireDeferred(\\"Something...\\")\\n```","params":[{"name":"...","desc":"","lua_type":"any"}],"returns":[],"function_type":"method","source":{"line":604,"path":"src/NewSignal.luau"}},{"name":"FireSafe","desc":"Fires a Signal object with the arguments passed using a `pcall`.\\n\\n```lua\\nSignal:Connect(function(Text)\\n\\tprint(Text) --\x3e \\"Something...\\"\\nend)\\n\\nSignal:FireSafe(\\"Something...\\")\\n```","params":[{"name":"...","desc":"","lua_type":"any"}],"returns":[],"function_type":"method","source":{"line":632,"path":"src/NewSignal.luau"}},{"name":"DisconnectAll","desc":"Disconnects all current Connections from the Signal.\\n\\n```lua\\nSignal:Connect(function(Args) end)\\n\\nSignal:DisconnectAll()\\n```","params":[],"returns":[],"function_type":"method","source":{"line":658,"path":"src/NewSignal.luau"}},{"name":"DisconnectAllImmediate","desc":"Disconnects all current Connections from the Signal immediately.\\nThis can cause issues if not used carefully\\n\\n```lua\\nSignal:Connect(function(Args) end)\\n\\nSignal:DisconnectAllImmediate()\\n```","params":[],"returns":[],"function_type":"method","tags":["To be used Carefully"],"source":{"line":706,"path":"src/NewSignal.luau"}},{"name":"Destroy","desc":"Destroys a Signal object, disconnecting all connections and making it unusable.\\n\\n```lua\\nSignal:Connect(function(Args) end)\\n\\nSignal:Destroy() -- Destroys the signal and disconnects all connections\\n```","params":[],"returns":[],"function_type":"method","source":{"line":748,"path":"src/NewSignal.luau"}},{"name":"Fire","desc":"Alias for FireAsync by default.\\nCan be changed to any of the other fire methods by modiying the `DefaultFireMethod` variable.\\n\\n```lua\\nSignal:Connect(function(Text)\\n\\tprint(Text) --\x3e \\"Something...\\"\\nend)\\n\\nSignal:Fire(\\"Something...\\") -- Same behaviour as `FireAsync` by default\\n```","params":[],"returns":[],"function_type":"method","source":{"line":781,"path":"src/NewSignal.luau"}}],"properties":[],"types":[],"name":"Signal","desc":"A Signal is a class that is used to substitute the use of Bindable Events, this implementation\\ntries to handle most of the edge cases that could happen, while being as performant as possible,\\nwith additional features for Advanced users such as selectable disconnect mode.\\n\\nThis implementation tries to have similar API to the standard signal module, [GoodSignal](https://devforum.roblox.com/t/lua-signal-class-comparison-optimal-goodsignal-class/1387063),\\nwith some additional features.\\n\\nQuick example:\\n```lua\\nlocal NewSignal = require(path.to.NewSignal)\\n\\n-- Create a signal\\nlocal Signal = NewSignal.new()\\n\\n-- Connect a listener\\nlocal Connection = Signal:Connect(function(Param)\\n    print(`The Signal Got fired, param: {Param}`)\\nend)\\n\\n-- Fire the signal with the default method\\nSignal:Fire(\\"Hello\\")\\n\\n-- Disconnect the listener\\nConnection:Disconnect()\\n```","source":{"line":110,"path":"src/NewSignal.luau"}}')}}]);